using EarthUnscripted.TerrainDraft;using System;using System.Collections.Generic;using System.Linq;using System.Threading;using Clipper2Lib;
namespace EarthUnscripted.TerrainDraft.Core800 {
 public sealed class TerrainFootprintUnionResult {public IReadOnlyList<TerrainPoint>[] Contours;public int SourceTriangles,Calls,MaximumCallVertices,ZeroProjectedInputs;}
 public static class BoundedTerrainFootprintUnion {
  static long Q(double x)=>checked((long)Math.Round(x*ManagedTerrainDomainLocal.Scale,MidpointRounding.ToEven));
  // Every intersecting source triangle is consumed. Only the terrainMASK is
  // clipped/coalesced; original sourceasphalt/height/collider arrays are retained.
  public static TerrainFootprintUnionResult Build(int cellX,int cellZ,IReadOnlyList<TerrainPoint[]> sourceTriangles,int inputCap=4096,int callCap=1024,CancellationToken token=default,double padding=0,TerrainCellBounds? explicitBounds=null){if(sourceTriangles==null||sourceTriangles.Count>100000||inputCap<8||inputCap>4096||callCap<1)throw new TerrainBudgetException("Local completefootprint inputcap");var cell=explicitBounds??TerrainCellBounds.Global32(cellX,cellZ);var bounds=new Rect64(Q(cell.MinX-padding),Q(cell.MinZ-padding),Q(cell.MaxX+padding),Q(cell.MaxZ+padding));var current=new Paths64();int cursor=0,calls=0,max=0,zero=0;
   while(cursor<sourceTriangles.Count){token.ThrowIfCancellationRequested();int used=current.Sum(p=>p.Count),available=inputCap-used,count=Math.Min(256,Math.Max(1,available/7));var batch=new Paths64();for(int i=0;i<count&&cursor<sourceTriangles.Count;i++,cursor++){var t=sourceTriangles[cursor];if(t==null||t.Length!=3)throw new ArgumentException("Sourcefootprint must be originaltriangle");var path=new Path64();foreach(var v in t){if(!TerrainFieldLimits.Finite(v.X)||!TerrainFieldLimits.Finite(v.Y)||!TerrainFieldLimits.Finite(v.Z)||Math.Abs(v.X)>20000||Math.Abs(v.Z)>20000)throw new ArgumentException("Invalid sourcefootprint");path.Add(new Point64(Q(v.X),Q(v.Z)));}if(Clipper.Area(path)==0)zero++;if(!Clipper.IsPositive(path))path.Reverse();batch.Add(path);}if(batch.Sum(p=>p.Count)>inputCap)throw new TerrainBudgetException("Rectclip inputcap");if(++calls>callCap)throw new TerrainBudgetException("Footprint Booleancallcap");var clipped=Clipper.RectClip(bounds,batch);int vertices=clipped.Sum(p=>p.Count)+used;max=Math.Max(max,vertices);if(vertices>inputCap)throw new TerrainBudgetException("Denseunion requires finerpreparationcells, neverpartialsource");if(clipped.Count==0)continue;var combined=new Paths64(current);combined.AddRange(clipped);token.ThrowIfCancellationRequested();current=Clipper.Union(combined,FillRule.NonZero);if(current.Sum(p=>p.Count)>inputCap)throw new TerrainBudgetException("Unionoutput cap");}
   token.ThrowIfCancellationRequested();return new TerrainFootprintUnionResult{Contours=current.Select(path=>(IReadOnlyList<TerrainPoint>)path.Select(p=>new TerrainPoint((double)p.X/ManagedTerrainDomainLocal.Scale,0,(double)p.Y/ManagedTerrainDomainLocal.Scale)).ToArray()).ToArray(),SourceTriangles=cursor,Calls=calls,MaximumCallVertices=max,ZeroProjectedInputs=zero};
  }
 }
}
